'use strict';

// MODULES //

var addon = require( './../src/addon.node' );


// MAIN //

/**
* Evaluates the quantile function for a studentized range distribution with `r` samples and `v` degrees of freedom.
*
* @private
* @param {Probability} p - input probability
* @param {PositiveNumber} r - sample size for range (same for each group; must be greater than or equal to `2`)
* @param {PositiveNumber} v - degrees of freedom (must be greater than or equal to `2`)
* @returns {number} evaluated quantile function
*
* @example
* var y = quantile( 0.5, 3.0, 2.0 );
* // returns ~1.908
*
* @example
* var y = quantile( 0.9, 17.0, 2.0 );
* // returns ~11.237
*
* @example
* var y = quantile( 0.1, 3.0, 4.0 );
* // returns ~0.627
*
* @example
* var y = quantile( NaN, 3.0, 2.0 );
* // returns NaN
*
* @example
* var y = quantile( 0.5, NaN, 2.0 );
* // returns NaN
*
* @example
* var y = quantile( 0.5, 3.0, NaN );
* // returns NaN
*/
function quantile( p, r, v ) {
	return addon( p, r, v );
}


// EXPORTS //

module.exports = quantile;
